INSERT INTO `challenges` (`id`, `name`, `content`, `rank_point`, `deleted_at`, `created_at`, `updated_at`, `type`, `status`) VALUES
(1, 'Bài test Tate Lakin', 'Fugit et deleniti laborum eos pariatur rerum reiciendis delectus dolores nihil eos quae magnam laboriosam qui nulla excepturi culpa eum quia sit eligendi aut minima dolorem ut.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 08:59:06', '2022-10-12 08:59:06', 0, 1),
(2, 'Bài test Julia Brekke IV', 'Quibusdam quo enim voluptas aut et quasi aliquam possimus id occaecati odio aut provident eveniet.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 08:59:07', '2022-10-12 08:59:07', 0, 1),
(3, 'Bài test Mrs. Dorothea Lang', 'Ratione deserunt illum eveniet voluptate itaque dolorum harum sunt magnam totam iure qui deserunt sint voluptatum et perferendis illum repellendus.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:25', '2022-10-12 09:01:25', 0, 1),
(4, 'Bài test Dr. Adam Crooks III', 'Aspernatur excepturi ex tempore harum est eum et quia sunt non occaecati expedita ullam illum dolore corrupti rerum quod nihil esse odio impedit quis voluptate impedit voluptatem.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:26', '2022-10-12 09:01:26', 0, 1),
(5, 'Bài test Mrs. Pauline Bogan', 'Eveniet cupiditate beatae pariatur odit quibusdam nemo accusamus adipisci necessitatibus iusto modi omnis qui nam et.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:28', '2022-10-12 09:01:28', 0, 1),
(6, 'Bài test Xzavier Kuphal', 'Aut itaque explicabo iste aut quae facere et cupiditate fugit rerum animi ea incidunt aliquid ab quibusdam quaerat ipsum ut quia recusandae.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:28', '2022-10-12 09:01:28', 0, 1),
(7, 'Bài test Pasquale Bosco', 'Labore debitis molestias expedita eum soluta omnis nisi expedita libero similique quae ad sed illo consequatur nobis vitae quidem et.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:54', '2022-10-12 09:01:54', 0, 1),
(8, 'Bài test Jimmy Lowe', 'Molestiae excepturi soluta illo saepe dolores veritatis ea sunt nulla laudantium enim deleniti ipsum at dolorem.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:54', '2022-10-12 09:01:54', 0, 1),
(9, 'Bài test Walter Lynch', 'Cumque sequi ut est aut magni atque debitis amet aut atque doloribus praesentium odio et sequi magni suscipit.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:56', '2022-10-12 09:01:56', 0, 1),
(10, 'Bài test Mr. Elwyn O\'Keefe V', 'Nisi illum perferendis non non eveniet ad nam et blanditiis enim corrupti laboriosam qui iusto repudiandae aut.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:56', '2022-10-12 09:01:56', 0, 1),
(11, 'Bài test Prof. Delia Weissnat IV', 'Placeat voluptates ea numquam minus similique distinctio quidem aliquid quidem iure dolorem exercitationem dolore porro eos maxime est odio.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:58', '2022-10-12 09:01:58', 0, 1),
(12, 'Bài test Onie Nitzsche', 'Nam ut ut enim totam facilis qui harum veritatis quo incidunt expedita repudiandae quam animi magnam nisi sit id tempora nulla itaque.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:01:58', '2022-10-12 09:01:58', 0, 1),
(13, 'Bài test Mitchell Abshire PhD', 'Quia corporis eaque officia optio ad repellat est sit ut libero ipsum quis odio odit quasi labore deserunt pariatur distinctio ut iusto est quia ab autem nesciunt accusantium.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:02:01', '2022-10-12 09:02:01', 0, 1),
(14, 'Bài test Prof. Joe Emmerich DVM', 'Vel impedit ut aliquid aut quo officia aut qui rerum in repudiandae a ratione et architecto dolorem vitae.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:02:02', '2022-10-12 09:02:02', 0, 1),
(15, 'Bài test Kaden Hilpert V', 'Tempora enim distinctio ut eum quasi sit nihil accusamus odit nulla nesciunt et ut maxime quae velit similique suscipit in assumenda vel quas facilis architecto aperiam quae eaque.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:02:03', '2022-10-12 09:02:03', 0, 1),
(16, 'Bài test Enrico Kling II', 'Officiis rerum et qui ut molestiae aut esse est omnis earum qui nulla voluptates quis quasi minima velit quas doloribus vero reprehenderit commodi est est ea.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:02:04', '2022-10-12 09:02:04', 0, 1),
(17, 'Bài test Angelita Rohan', 'Qui nisi consectetur nostrum est esse delectus ea nihil facilis nulla aut veniam nihil rerum.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:21:38', '2022-10-12 09:21:38', 0, 1),
(18, 'Bài test Ella Swift', 'Laudantium sed pariatur iste voluptas eum magnam dolor voluptas et velit esse pariatur optio eligendi velit tempore autem tenetur voluptatibus magni.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:21:43', '2022-10-12 09:21:43', 0, 1),
(19, 'Bài test Colby Wilderman', 'Deserunt rerum provident ad ad neque fuga ut velit minima ut at libero assumenda at velit eum debitis ea ratione nesciunt in veniam aspernatur excepturi inventore.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:04', '2022-10-12 09:22:04', 0, 1),
(20, 'Bài test Elroy Dare', 'Rerum accusamus soluta labore ea natus praesentium et optio similique facilis similique consequatur quis dolorum eius voluptates molestias magni.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:05', '2022-10-12 09:22:05', 0, 1),
(21, 'Bài test Leland Rice', 'Aut aut similique sint aut iusto consequatur molestiae dolore ipsum ex dolorem repudiandae ea molestiae ut.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:06', '2022-10-12 09:22:06', 0, 1),
(22, 'Bài test Geovanni Kulas', 'Dignissimos rerum assumenda fugit vel veritatis sit saepe itaque est ipsa ab sed consequatur maiores voluptas placeat.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:12', '2022-10-12 09:22:12', 0, 1),
(23, 'Bài test Lula Nienow IV', 'Minima sunt sapiente dolore explicabo dolor repellendus quia aut non voluptatem aut omnis esse rem voluptatibus sunt consequatur dicta dicta pariatur deleniti porro officiis sed.', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:26', '2022-10-12 09:22:26', 0, 1),
