(25, 'Giải phương trình bậc nhất 1 ẩn', '<p>Accusantium officiis sit voluptatem voluptas esse quidem illum eum nesciunt deserunt impedit enim voluptatem sed incidunt animi voluptatem ipsa in ut.</p>', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:32', '2022-10-30 06:50:11', 0, 1),
(26, 'Kiểm tra năm nhuận', '<p>Atque aut ut explicabo quia optio cupiditate quia molestiae non quidem et magnam dignissimos dicta.</p>', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:32', '2022-10-30 06:49:51', 0, 1),
(27, 'Tìm thuật toán tối ưu', '<p>Quaerat est repudiandae qui minus velit eos rerum natus minus ratione dignissimos ab sint distinctio ratione eveniet libero maiores quia aut dolorem fuga eius consequatur unde.</p>', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:32', '2022-10-30 06:49:09', 0, 1),
(28, 'Tìm số lớn nhất', '<p>Laborum qui aut veritatis autem aut molestiae voluptate est laboriosam et non molestiae eaque commodi quia quod quae quam odit laborum corporis ea est eius quibusdam laudantium ut.</p>', '{\"top1\": \"10\", \"top2\": \"9\", \"top3\": \"8\", \"leave\": \"5\"}', NULL, '2022-10-12 09:22:32', '2022-10-30 06:49:35', 0, 1),
