INSERT INTO `enterprises` (`id`, `name`, `created_at`, `updated_at`, `deleted_at`, `description`, `status`, `logo`, `link_web`, `branch_id`, `address`) VALUES
(2, 'Công Ty Cổ Phần Thực Phẩm Và Dịch Vụ My Way', '2022-06-06 17:21:11', '2022-12-24 09:05:07', NULL, '<p>Công ty Cổ phần Thực phẩm và Dịch vụ My Way cung cấp các dịch vụ tổ chức tiệc, sự kiện, tổ chức hội thảo-hội nghị theo yêu cầu. Điểm mạnh của công ty là ...</p>', 1, '63a4230fb416b-1671701263.png', 'https://mywaymyfashion.com/', 0, NULL),
(3, 'Công ty cổ phần phần mềm Luvina', '2022-06-06 17:24:42', '2022-12-24 09:05:06', NULL, '<p>Công ty cổ phần phần mềm Luvina chuyên thực hiện thiết kế, phát triển, bảo trì và vận hành các sản phẩm công nghệ thông tin chuyên cho thị trường Nhật Bản.</p>', 1, '63a4238515379-1671701381.jpg', 'https://luvina.net/vi', 0, NULL),
(4, 'Công ty VINPEARL', '2022-06-06 17:28:57', '2022-12-24 09:05:04', NULL, '<p>Vinpearl là thương hiệu dịch vụ du lịch - nghỉ dưỡng - giải trí lớn nhất Việt Nam. Vinpearl sở hữu chuỗi thương hiệu khách sạn, resort, spa cùng trung tâm hội nghị, ẩm thực và sân golf đẳng cấp 5 sao và các khu vui chơi giải trí theo tiêu chuẩn quốc tế toạ lạc tại những danh thắng du lịch nổi tiếng nhất của Việt Nam. Với 18 năm không ngừng phát triển, 45 cơ sở thuộc thương hiệu Vinpearl đang có mặt tại 17 tỉnh thành trên toàn quốc với công suất trên 18.500 phòng khách sạn và biệt thự, 3 công viên chủ đề và 2 khu vui chơi giải trí, 2 công viên bảo tồn và chăm sóc động vật bán hoang dã, 4 sân golf, dự kiến tiếp tục mở rộng quy mô trên Việt Nam và trên thế giới trong thời gian tới.</p>', 1, '629e395945d60-1654536537.png', 'https://vinpearl.club/', 0, NULL),
(5, 'Công Ty Cổ Phần Appota', '2022-06-07 01:15:55', '2022-12-24 09:05:03', NULL, '<p>Appota là đơn vị tiên phong và dẫn đầu tại Việt Nam cung cấp nền tảng phân phối ứng dụng mobile một cách toàn diện cho các nhà phát triển ứng dụng và phát hành game, giúp phân phối hiệu quả đến cộng đồng sử dụng smartphone lớn nhất Việt Nam. Đến cuối năm 2013, Appota đã hợp tác với hơn 8.200 nhà phát triển và phát hành trên toàn cầu, bao gồm cả những tên tuổi lớn như Zepto Lab, NHN, Kakao, VNG, VTC Online, FPT Online, InMobi, Metaps... Appota cũng hợp tác với các kênh phân phối sở hữu hơn 15 triệu người dùng smartphone tại Đông Nam Á và Việt Nam.</p>', 1, '629ea6cae44c9-1654564554.png', 'https://appota.com/', 0, NULL),
(6, 'TPBank Ngân hàng dẫn đầu Kỷ nguyên Số', '2022-06-07 01:17:08', '2022-12-25 14:45:14', NULL, '<p>Website chính thức và duy nhất của <i><strong>TPBank</strong></i> – Ngân hàng Số dẫn đầu Việt Nam. Chúng tôi luôn nỗ lực để mang tới cho Quý khách trải nghiệm ngân hàng đích thực&nbsp;...</p>', 0, '63a861f9ddf0c-1671979513.png', 'https://tpb.vn/', 0, NULL),
(7, 'FPT Software', '2022-06-07 01:19:24', '2022-06-07 01:19:24', NULL, 'FPT Software là tên gọi khác của công ty TNHH Phần Mềm FPT với nhiệm vụ chính là gia công phần mềm tại Việt Nam và nước ngoài.\r\n\r\n \r\n\r\nThành lập từ năm 1988 đến nay với 3 Trụ sở chính FPT Software đặt tại Việt Nam và một số nước trên toàn thế giới như Hoa Kỳ, Nhật Bản, Malaysia, Đức, Úc, Singapore, Malaysia, Thái Lan và Philipines hiện FPT Software đáp ứng nhu cầu gia công phần mềm lớn cho hơn 150 công ty hàng đầu tại 20 quốc gia lớn nhất trên thế giới hiện nay với các hợp đồng lớn có khi đạt cả 1 triệu USD dành cho một số đối tác lớn như Hitachi, NEOPOST, Petronas, Deutsche Bank, và Unilever với hơn 4000 nhân viên trên toàn thế giới.', 1, '629ea79c713fa-1654564764.png', NULL, 0, NULL),
(8, 'TopCV Tuyển dụng hiệu quả với TopCV', '2022-06-18 14:55:45', '2022-12-25 14:39:32', NULL, '<p>Tạo CV online &amp; tìm việc làm miễn phí trên TopCV ngay hôm nay để tiếp cận 30.000+ cơ hội việc làm được kết nối thành công trên TopCV mỗi ngày.</p>', 1, '63a860a4c5734-1671979172.png', 'https://www.topcv.vn/', 0, NULL),
(9, 'SETA International Digital Transformation', '2022-06-27 05:38:03', '2022-12-25 14:37:07', NULL, '<p>SETA International is a global software company • Our vision: To be global leading technology company. Currently, we have head office in US, ...</p>', 0, '63a8601395fd6-1671979027.png', 'https://www.seta-international.com/', 0, NULL),
(10, 'Vietcombank', '2022-07-02 14:50:03', '2022-12-25 14:38:07', NULL, '<p>Ngân hàng TMCP Ngoại thương Việt Nam tên viết tắt: \"Vietcombank\", là công ty lớn nhất trên thị trường chứng khoán Việt Nam tính theo vốn hóa.</p>', 0, '63a8604ed25b6-1671979086.jpg', 'https://www.vietcombank.com.vn/', 0, NULL),
(11, 'cty a', '2022-07-11 06:18:10', '2022-07-11 17:04:23', '2022-07-11 17:04:23', '<p>chjkclkscjlkasckslc</p>', 0, '62cbc0a1ca563-1657520289.png', 'https://matpetfamily.com/', 0, NULL),
(12, 'Viettel Telecom', '2022-07-11 17:45:56', '2022-12-25 14:34:20', NULL, '<p>Cung cấp thông tin đầy đủ, chính xác mọi Dịch vụ, Khuyến mại của <i><strong>Viettel Telecom</strong></i>. Đăng nhập để tận hưởng thế giới Ưu đãi &amp; dịch vụ Chăm sóc khách hàng tốt&nbsp;...</p>', 1, '63a85f6c2f4f0-1671978860.png', 'https://vietteltelecom.vn/', 0, NULL),
(13, 'CÔNG TY TNHH THƯƠNG MẠI VÀ DỊCH VỤ CÔNG NGHỆ AHT', '2022-07-11 17:47:27', '2022-12-25 14:32:24', NULL, '<p>AHT chuyên thiết kế website về tất cả các lĩnh vực ,AHT luôn đồng hành với khách hàng trong và ngoài nước, website luôn chuẩn seo, thao tác dễ dàng cho ...</p>', 0, '63a85ef870493-1671978744.png', 'https://ahtvietnam.vn/', 0, NULL),
(14, 'TMA Solutions', '2022-08-07 16:23:19', '2022-12-22 09:24:55', NULL, '<p>TMA tự hào đã nhận được sự tin cậy của hơn 100 khách hàng từ hơn 30 quốc gia trên toàn thế giới, có sự phát triển bền vững suốt 24 năm.</p>', 1, '63a422549bf9f-1671701076.jfif', 'https://www.tma.vn/', 0, NULL),
(15, 'FPT Shop', '2022-08-30 01:42:39', '2022-12-25 14:30:24', NULL, '<p>Hàng 100% chính hãng được phân phối bởi hệ thống bán lẻ kỹ thuật số <i><strong>FPTShop</strong></i> cùng với nhiều khuyến mãi hấp dẫn, bảo hành chính hãng. Mua trực tuyến giá rẻ&nbsp;...</p>', 0, '63a85e805da8e-1671978624.png', 'https://fptshop.com.vn/', 0, NULL),
(16, 'Công ty cổ phần VCCorp', '2022-08-30 02:22:15', '2022-12-22 09:23:07', NULL, '<p>VCCorp - Công ty Công Nghệ hàng đầu Việt Nam, các sản phẩm của <i><strong>VCCorp</strong></i> có độ phủ sóng mạnh trên hầu hết các lĩnh vực về Công Nghệ và Internet như: thương mại&nbsp;...</p>', 1, '63a421fb39cfd-1671700987.png', 'https://vccorp.vn/', 0, NULL),
(17, 'Công Ty Cổ Phần Công Nghệ Cloudify Việt Nam', '2022-09-16 17:56:05', '2022-12-22 09:26:16', NULL, '<p>Cloudify là đơn vị cung cấp các gói giải pháp quản lý doanh nghiệp toàn diện Cloud ERP, online 24/7 trên nền tảng điện toán đám mây theo chuẩn quốc tế.</p>', 1, '63a422b87b0f3-1671701176.png', 'https://cloudify.vn/', 0, NULL),
(19, 'Công ty Cổ phần SmartOSC', '2022-09-29 17:44:56', '2022-12-22 09:21:40', NULL, '<p>SmartOSC là đơn vị tiên phong &amp; dẫn đầu trong lĩnh vực cung cấp giải pháp thương mại điện tử (TMĐT) đa kênh trên quy mô toàn cầu.</p>', 1, '63a421a4d6b01-1671700900.png', 'https://www.smartosc.com/', 0, NULL),
(20, 'Tuân BG', '2022-10-03 11:34:25', '2022-10-03 11:34:57', '2022-10-03 11:34:57', '<figure class=\"media\"><oembed url=\"https://www.facebook.com/LeVanTuan.Info/\"></oembed></figure>', 0, '633ac8c01f1d8-1664796864.jpg', 'https://www.facebook.com/LeVanTuan.Info/', 0, NULL);
