(33, 'bài 1', '62efdd4774f94-1659886919.jpg', '2022-08-07 22:40:45', '2022-08-07 22:40:57', '<p>xsdfgy</p>', 29, '2022-08-07 15:42:00', '2022-08-07 15:42:00', 1, NULL, NULL, 15, 0),
(34, 'Vòng sơ loại thiết kế logo', '62fc96563f81e-1660720726.png', '2022-08-17 14:13:50', '2022-08-31 14:13:56', '<p>vòng Sơ loại kéo dài từ ngày 7/6 – 25/6/2021, thí sinh nộp sản phẩm gồm mẫu thiết kế logo kèm thông tin mô tả ý tưởng vào đường link đăng ký: <a href=\"http://bit.ly/logo15namFPTU\">http://bit.ly/logo15namFPTU</a>. BTC sẽ chọn ra những bài chất lượng đủ tiêu chí và yêu cầu cuộc thi để bước vào vòng thi thứ hai. Kết quả sẽ được công bố vào ngày 03/08/2022.</p>', 33, '2022-08-17 07:18:47', '2022-08-17 07:18:47', 1, NULL, NULL, NULL, NULL),
(35, 'Bình chọn online', '62fc98271b925-1660721191.jpg', '2022-09-05 14:22:39', '2022-09-17 13:22:49', '<p>Ở vòng Bình chọn online, các bài dự thi sẽ được đăng tải trên fanpage FPT Education với số điểm lấy từ ý kiến cộng đồng mạng. Theo đó, mỗi lượt Like trên mỗi bài dự thi được tính là 1 điểm và mỗi lượt Share trên mỗi bài dự thi được tính là 5 điểm. BTC sẽ ủy quyền cho một bên thứ 3 kiểm tra số lượt bình chọn để đảm bảo tính công bằng của cuộc thi và công bố kết quả vào ngày 17/09/2022.</p>', 33, '2022-08-17 07:26:31', '2022-08-17 07:27:05', 1, NULL, NULL, NULL, NULL),
(36, 'Vòng khởi động cuộc thi FE', '62fd266a4d33e-1660757610.jpeg', '2022-08-18 00:31:35', '2022-08-24 15:31:41', '<p>Vòng khởi động.</p><p><i><strong>Cuộc thi lập trình</strong> là sân chơi chuyên nghiệp, bổ ích giúp các lập trình viên thể hiện bản thân, từng bước kiến tạo dấu ấn trong hành trình phát triển sự nghiệp của chính mình.&nbsp;</i></p><p><i>Ngày nay, với sự phát triển mạnh mẽ của công nghệ và nhu cầu lập trình của các doanh nghiệp lớn nhỏ ngày càng cao, các cuộc thi lập trình này luôn thu hút một lượng thí sinh vô cùng đông đảo.</i></p>', 34, '2022-08-17 17:33:30', '2022-08-17 18:12:56', 1, NULL, NULL, NULL, NULL),
(37, 'Vòng kết thúc cuộc thi FE', '62fd269d562a0-1660757661.jpeg', '2022-08-26 00:33:47', '2022-08-26 16:33:51', '<p>Vòng kết thúc.</p><p><i><strong>Cuộc thi lập trình</strong> là sân chơi chuyên nghiệp, bổ ích giúp các lập trình viên thể hiện bản thân, từng bước kiến tạo dấu ấn trong hành trình phát triển sự nghiệp của chính mình.&nbsp;</i></p><p><i>Ngày nay, với sự phát triển mạnh mẽ của công nghệ và nhu cầu lập trình của các doanh nghiệp lớn nhỏ ngày càng cao, các cuộc thi lập trình này luôn thu hút một lượng thí sinh vô cùng đông đảo.</i></p>', 34, '2022-08-17 17:34:21', '2022-08-17 17:34:21', 1, NULL, NULL, NULL, NULL),
