(39, 'Vòng gửi xe', '6319ed639a8a8-1662643555.png', '2022-09-08 20:24:59', '2022-09-30 20:25:05', '<p>Try this:</p><p>&lt;div *ngFor=\"let childitem of menuitem.MenuRoutes\"&gt;\r\n&lt;a [routerLink]=\"menuitem.IsMain ? [childitem.Route] : []\"&gt;&lt;a&gt;\r\n&lt;/&gt;\r\n</p><p><a href=\"https://stackoverflow.com/a/62256551\">Share</a></p><p>Follow</p><p><a href=\"https://stackoverflow.com/posts/62256551/revisions\">edited Jun 8, 2020 at 7:54</a></p><figure class=\"image\"><img src=\"https://www.gravatar.com/avatar/2a262f4c7f71392806f969febe970961?s=64&amp;d=identicon&amp;r=PG&amp;f=1\" alt=\"user avatar\"></figure><p><a href=\"https://stackoverflow.com/users/4731718/%d7%a1%d7%98%d7%a0%d7%9c%d7%99-%d7%92%d7%a8%d7%95%d7%a0%d7%9f\">סטנלי גרונן</a></p><p><strong>2,849</strong>2323 gold badges4646 silver badges6565 bronze badges</p><p>answered Jun 8, 2020 at 6:53</p><figure class=\"image\"><img src=\"https://www.gravatar.com/avatar/8679e431a1ac219daba9b422bb87f46a?s=64&amp;d=identicon&amp;r=PG&amp;f=1\" alt=\"user avatar\"></figure><p><a href=\"https://stackoverflow.com/users/9934311/erick\">Erick</a></p><p><strong>1</strong></p>', 35, '2022-09-08 13:25:56', '2022-09-08 13:25:56', 1, NULL, NULL, NULL, NULL),
