(280, 'Test', '629ed9aa83da8-1654577578.jpg', '2022-10-04 00:00:00', '2022-10-11 00:00:00', 'Người đàn ông tình nguyện vì bạn mà theo đuổi mọi thứ chưa hẳn đã thật lòng yêu bạn, bởi vì thứ mà anh ta theo đuổi được không hẳn thuộc về bạn.', 24, '2022-10-07 15:06:35', '2022-10-07 15:06:35', 1, NULL, NULL, NULL, NULL),
(281, 'Vòng thi cuộc thi Static Saab B - third Banana C - second Instance Apple See9Ak3nqXna7', '629e322834552-1654534696.jpg', '2022-10-02 00:00:00', '2022-10-09 00:00:00', 'Cuộc sống không phải là phim ảnh, không có nhiều đến thế… những lần không hẹn mà gặp.', 25, '2022-10-07 15:06:36', '2022-10-07 15:06:36', 1, NULL, NULL, NULL, NULL),
(283, 'Vòng thi cuộc thi properties BMW B - second Mango C - first Examples Strawberry Notes3tgG0ISsiv', '629ec3be1f1fc-1654571966.jpg', '2022-10-03 00:00:00', '2022-10-24 00:00:00', 'Đừng chỉ vì ai đó trông mạnh mẽ, không có nghĩa là tất cả mọi thứ đều ổn. Ngay cả những người mạnh mẽ nhất cũng cần một người bạn để dựa vào vai mà khóc. Hãy kết hôn với người mà bạn thích chuyện trò với người đó, vì khi bạn già đi, bạn sẽ phát hiện, thích chuyện trò là một ưu điểm lớn.', 30, '2022-10-07 15:06:37', '2022-10-07 15:06:37', 1, NULL, NULL, NULL, NULL),
(284, 'Vòng thi cuộc thi Description BMW B - second Orange C - third Instance Cherry alsoKog3nLG0lr', '62b58157f38e3-1656062295.jpg', '2022-09-04 00:00:00', '2022-09-11 00:00:00', 'Người đàn ông tình nguyện vì bạn mà theo đuổi mọi thứ chưa hẳn đã thật lòng yêu bạn, bởi vì thứ mà anh ta theo đuổi được không hẳn thuộc về bạn.', 31, '2022-10-07 15:06:38', '2022-10-07 15:06:38', 1, NULL, NULL, NULL, NULL),
(285, 'Vòng thi cuộc thi Constructor Volvo B - third Orange C - first Examples Cherry SeemzQ200DGpi', '62a9f2843f66e-1655304836.jpg', '2022-10-01 00:00:00', '2022-10-08 00:00:00', 'Trong cuộc sống, không tránh khỏi lúc bạn đưa ra quyết định sai lầm. Nhưng nếu bạn đổ lỗi cho người khác vì lỗi lầm của mình… thì bạn vẫn chưa chín chắn đâu.', 33, '2022-10-07 15:06:38', '2022-10-07 15:06:38', 1, NULL, NULL, NULL, NULL),
(286, 'Vòng thi cuộc thi Static Volvo B - first Apple C - third Instance Mango NotesE1cN3akk1P', '62b58157f38e3-1656062295.jpg', '2022-10-02 00:00:00', '2022-10-30 00:00:00', 'Rủi ro lớn nhất là chẳng đối mặt với rủi ro nào. Trong một thế giới đang thay đổi rất nhanh, chiến lược mà chắc chắn sẽ thất bại chính là tránh xa các rủi ro – Mark Zuckerberg', 34, '2022-10-07 15:06:39', '2022-10-07 15:06:39', 1, NULL, NULL, NULL, NULL),
(287, 'Vòng thi cuộc thi Constructor Saab B - second Apple C - second Instance Apple Notes0KtgKL3M85', '629ed417db9a2-1654576151.png', '2022-10-01 00:00:00', '2022-10-15 00:00:00', 'Hãy cố biến mọi thảm họa thành cơ hội – John Rockefeller.', 35, '2022-10-07 15:06:40', '2022-10-07 15:06:40', 1, NULL, NULL, NULL, NULL),
(303, 'Vòng thi cuộc thi properties Saab B - third Apple C - third properties Cherry SeeNLDyV3hVoq', '629ecb1f9c36a-1654573855.jpg', '2022-10-01 00:00:00', '2022-10-22 00:00:00', 'Tôi nghĩ hầu hết những lời khuyên tiết kiệm cho giới trẻ là sai lầm. Tôi chẳng bao giờ tiết kiệm xu nào cho đến khi 40 tuổi. Thay vào đó, tôi đầu tư cho chính mình, học hành, làm chủ các kỹ năng và chuẩn bị. Những người bỏ vài đô la vào ngân hàng mỗi tuần sẽ làm tốt hơn nhiều nếu bỏ nó vào chính họ – Henry Ford', 24, '2022-10-07 15:07:06', '2022-10-07 15:07:06', 1, NULL, NULL, NULL, NULL),
