INSERT INTO `skills` (`id`, `created_at`, `updated_at`, `name`, `short_name`, `image_url`, `deleted_at`, `description`) VALUES
(1, '2022-06-06 14:06:35', '2022-12-21 08:05:46', 'Lập trình Java 1', 'MOB1014', '63a2be59da80a-1671609945.jpeg', NULL, '<p>Java là một trong những ngôn ngữ lập trình hướng đối tượng. Nó được sử dụng trong phát triển phần mềm, trang web, game hay ứng dụng trên các thiết bị di động. Java được khởi đầu bởi James Gosling và bạn đồng nghiệp ở Sun MicroSystem năm 1991. Ban đầu Java được tạo ra nhằm mục đích viết phần mềm cho các sản phẩm gia dụng, và có tên là Oak.</p>'),
(2, '2022-06-06 14:07:27', '2022-06-06 14:07:27', 'Lập trình PHP', 'PHP', '629e0a1eb17e1-1654524446.jpg', NULL, 'PHP (viết tắt đệ quy của PHP: Hypertext Preprocessor) là tập hợp con của các ngôn ngữ script như JavaScript và Python. Sự khác biệt là ngôn ngữ PHP chủ yếu được sử dụng để giao tiếp phía server trong khi JavaScript có thể được sử dụng cho cả frontend cũng như backend và Python – chỉ dành cho phía client (backend).'),
(3, '2022-06-06 14:09:25', '2022-12-21 08:06:47', 'Lập trình cơ sở với Javascript', 'JS', '629e0a950f5dd-1654524565.png', NULL, '<p>JavaScript là 1 trong 3 ngôn ngữ chính của lập trình web, và nó được dùng phổ biến trong suốt 20 năm qua. Từ thuở sơ khai, nó còn có tên là Mocha (năm 1995), sau đó được đổi thành Mona, Livescript, và cuối cùng là JavaScript như hiện nay. Tính đến năm 2016, có đến 92% trang web hiện nay đang sử dụng JavaScript, và rất có thể bạn đã dùng qua rất nhiều trang web có sử dụng ngôn ngữ lập trình này.</p>'),
(4, '2022-06-06 14:32:00', '2022-06-06 14:32:00', 'Lập trình ECMAScript', 'WEB503', '629e0fe008726-1654525920.png', NULL, 'JavaScript là 1 trong 3 ngôn ngữ chính của lập trình web, và nó được dùng phổ biến trong suốt 20 năm qua. Từ thuở sơ khai, nó còn có tên là Mocha (năm 1995), sau đó được đổi thành Mona, Livescript, và cuối cùng là JavaScript như hiện nay.\r\n\r\nTính đến năm 2016, có đến 92% trang web hiện nay đang sử dụng JavaScript, và rất có thể bạn đã dùng qua rất nhiều trang web có sử dụng ngôn ngữ lập trình này.'),
(5, '2022-06-06 14:33:02', '2022-06-06 14:33:02', 'Lập trình TypeScript', 'WEB502', '629e101ea4510-1654525982.png', NULL, 'JavaScript là 1 trong 3 ngôn ngữ chính của lập trình web, và nó được dùng phổ biến trong suốt 20 năm qua. Từ thuở sơ khai, nó còn có tên là Mocha (năm 1995), sau đó được đổi thành Mona, Livescript, và cuối cùng là JavaScript như hiện nay.\r\n\r\nTính đến năm 2016, có đến 92% trang web hiện nay đang sử dụng JavaScript, và rất có thể bạn đã dùng qua rất nhiều trang web có sử dụng ngôn ngữ lập trình này.'),
(6, '2022-06-06 14:34:22', '2022-06-06 14:34:22', 'NodeJs   Restful Web Service', 'WEB501', '629e106de4d03-1654526061.jpg', NULL, 'JavaScript là 1 trong 3 ngôn ngữ chính của lập trình web, và nó được dùng phổ biến trong suốt 20 năm qua. Từ thuở sơ khai, nó còn có tên là Mocha (năm 1995), sau đó được đổi thành Mona, Livescript, và cuối cùng là JavaScript như hiện nay.\r\n\r\nTính đến năm 2016, có đến 92% trang web hiện nay đang sử dụng JavaScript, và rất có thể bạn đã dùng qua rất nhiều trang web có sử dụng ngôn ngữ lập trình này.'),
(7, '2022-06-06 14:36:03', '2022-06-06 14:36:03', 'Thiết kế hình ảnh với Photoshop', 'MUL1014', '629e10d2e31b1-1654526162.png', NULL, 'Như đã nói ở trên photoshop là phần mềm được phát triển với chức năng chính để chỉnh sửa hình ảnh. Trong lĩnh vực thiết kế Ps là phần mềm bắt buộc phải biết của các designer. Không chỉ được sử dụng để chỉnh sửa ảnh; photoshop được sử dụng rất nhiều trong thiết kế hiển thị. Hiện nay Ps được xem là phần mềm đồ họa bitmap mạnh nhất trên thị trường. Photoshop cũng được đưa vào giáo trình giảng dạy chính thức của các trường đào tạo nghề cũng như các trường cao đẳng, đại học.'),
(8, '2022-06-06 14:38:05', '2022-06-06 14:38:05', 'Thiết kế minh họa với Illustrator', 'MUL1023', '629e114d7791e-1654526285.png', NULL, 'Illustrator là thiết kế đồ họa có sự kết hợp giữa các thuật toán, đường giới hạn, đối tượng hình học, text để tạo thành một tượng vector. Các hình ảnh được tạo ra từ vẽ hoặc thiết kế Illustrator được gọi là hình minh họa. Chúng được sử dụng phổ biến trong thiết kế đồ họa, quảng cáo, dựng phim, in ấn,…'),
(9, '2022-06-06 14:48:00', '2022-12-21 08:12:52', 'Kế toán nhà hàng khách sạn', 'ACC105', '62cdbdef071cd-1657650671.jpg', NULL, '<p>Làm kế toán nhà hàng khách sạn tưởng chừng là những công việc rất đơn giản vì bạn nghĩ đó là những công việc dịch vụ đơn thuần và đưa hết vào doanh thu dịch vụ. Tuy nhiên thực tế cho thấy, đây không phải là công việc dễ dàng. Vậy họ đang làm những công việc gì? Họ cần chuẩn bị những kiến thức gì? Mời bạn cùng 1ketoan tìm hiểu qua bài viết dưới đây:</p>'),
(11, '2022-07-12 15:47:03', '2022-12-21 08:14:47', 'Cơ sở công nghệ gia công kim loại', 'ACC1055', '62cd977719db8-1657640823.png', NULL, '<p>Cơ sở công nghệ gia công kim loại</p>'),
