(1, 'Tự luận', '2022-06-06 16:14:16', '2022-06-06 16:14:16', 'Nihil praesentium libero dolorem dolores consequatur magnam aut. Sint voluptate impedit unde mollitia. Nam illum eos cupiditate id dignissimos ut.', NULL),
(2, 'Trắc nhiệm', '2022-06-06 16:14:17', '2022-06-06 16:14:17', 'Cumque quisquam quia consequatur deserunt in. Placeat architecto mollitia doloremque modi dolorem. Cum alias cupiditate et quam soluta. Ut autem blanditiis at enim incidunt reiciendis.', NULL),
(3, 'Vấn đáp', '2022-06-06 16:14:17', '2022-06-06 16:14:17', 'Quia impedit earum totam est voluptatem et laboriosam. Impedit fugiat ullam quidem ut consequatur beatae ipsa. Excepturi sit laborum veritatis modi.', NULL),
(4, 'Bảo vệ', '2022-06-06 16:14:17', '2022-06-06 16:14:17', 'Minima id aliquam est optio nihil et occaecati. Et facilis non cum qui rem a.', NULL),
(5, 'Thuyết trình', '2022-06-06 16:14:17', '2022-06-06 16:14:17', 'Cupiditate et dolores eum nostrum et. Sed nemo sapiente molestiae dignissimos sapiente sapiente mollitia. Voluptas expedita numquam cupiditate quibusdam fuga.', NULL);
